207		private static boolean isUnnamed(ProblemDetail problem) {
208			return problem.getType() == null || UNNAMED.equals(problem.getType());
209		}
210	
211		/**
212		 * Mapped from the status rather than from the exception class, with one refinement:
213		 * a body Jackson could not read and a body that failed its constraints are both
214		 * {@code 400} and are not the same news. Reading the status also keeps a server fault
215		 * that happens to carry a client-error exception type — {@code
216		 * ConversionNotSupportedException} is one — from telling the caller its input was
217		 * wrong.
218		 */
219		private static ProblemType typeOf(Exception exception, HttpStatusCode status) {
220			if (!status.is4xxClientError()) {
221				return ProblemType.INTERNAL_ERROR;
222			}
223			HttpStatus resolved = HttpStatus.resolve(status.value());
224			if (resolved == null) {
225				return ProblemType.CLIENT_ERROR;
226			}
227			return switch (resolved) {
228				case BAD_REQUEST -> exception instanceof HttpMessageNotReadableException
229						? ProblemType.MALFORMED_REQUEST
230						: ProblemType.VALIDATION_FAILED;
231				case NOT_FOUND -> ProblemType.NOT_FOUND;
232				case METHOD_NOT_ALLOWED -> ProblemType.METHOD_NOT_ALLOWED;
233				case UNSUPPORTED_MEDIA_TYPE -> ProblemType.UNSUPPORTED_MEDIA_TYPE;
234				default -> ProblemType.CLIENT_ERROR;
235			};
236		}
237	
238		private static List<Violation> violationsIn(BindingResult rejected) {
239			return sorted(rejected.getAllErrors().stream()
240					.map(error -> new Violation(fieldOf(error), messageOf(error))));
241		}
242	
243		private static List<Violation> violationsIn(HandlerMethodValidationException rejected) {
244			Stream<Violation> perParameter = rejected.getParameterValidationResults().stream()
245					.flatMap(result -> result.getResolvableErrors().stream()
246							.map(error -> new Violation(fieldOrParameterOf(error, result), messageOf(error))));
247			Stream<Violation> acrossParameters = rejected.getCrossParameterValidationResults().stream()
248					.map(error -> new Violation(null, messageOf(error)));
249			return sorted(Stream.concat(perParameter, acrossParameters));
250		}
251	
252		/**
253		 * Sorted, because Bean Validation promises no order and a form listing its errors
254		 * differently on every submission is a bug report waiting to be filed.
255		 */
256		private static List<Violation> sorted(Stream<Violation> violations) {
257			return violations
258					.sorted(Comparator.comparing(Violation::field, Comparator.nullsFirst(Comparator.naturalOrder()))
259							.thenComparing(Violation::message))
260					.toList();
261		}
262	
263		/** The fallback exists so that a constraint declared without a message cannot turn a 400 into a 500. */
264		private static String messageOf(MessageSourceResolvable error) {
265			String message = error.getDefaultMessage();
266			return message != null ? message : INVALID_VALUE;
267		}
268	
269		/**
270		 * The rejected value's position in the document, in the notation the rest of the
271		 * {@code errors} member uses: {@code currency}, {@code transfers[2].amountMinorUnits}.
272		 */
273		private static String memberPathOf(MismatchedInputException rejected) {
274			StringBuilder path = new StringBuilder();
275			for (Reference step : rejected.getPath()) {
276				if (step.getPropertyName() == null) {
277					path.append('[').append(step.getIndex()).append(']');
278				}
279				else {
280					path.append(path.isEmpty() ? "" : ".").append(step.getPropertyName());
281				}
282			}
283			return path.toString();
284		}
285	
286		/**
287		 * What the field will take, said without naming a Java type. An enum lists its
288		 * constants, which is the whole of what a closed set like {@code Currency} has to say
289		 * about itself.
290		 */
291		private static String messageFor(@Nullable Class<?> target) {
292			if (target == null) {
293				return INVALID_VALUE;
294			}
295			if (target.isEnum()) {
296				return Stream.of(target.getEnumConstants())
297						.map(Object::toString)
298						.collect(Collectors.joining(", ", "must be one of: ", ""));
299			}
300			return WHOLE_NUMBER_TYPES.contains(target) ? "must be a whole number" : INVALID_VALUE;
301		}
302	
303		private static @Nullable String fieldOf(MessageSourceResolvable error) {
304			return error instanceof FieldError fieldError ? fieldError.getField() : null;
305		}
306	
307		/** A constraint on the parameter itself has no field of its own; the parameter is one. */
308		private static @Nullable String fieldOrParameterOf(MessageSourceResolvable error,
309				ParameterValidationResult result) {
310			String field = fieldOf(error);
311			return field != null ? field : result.getMethodParameter().getParameterName();
312		}
313	}
