				.contentType(MediaType.APPLICATION_JSON)
				.content("""
						{"reference": "ok", "weight": -1}""")
				.exchange();

		assertThat(result).bodyJson()
				.extractingPath("$.errors[*].field").asInstanceOf(LIST)
				.containsExactly("weight");
